import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'
import {
  ADD_HINT_DESCRIPTION,
  HINT_KINDS,
  OTHER_INSTRUCTION,
  REMOVE_HINT_DESCRIPTION,
  activePathOf,
  appendHint,
  displayName,
  findItem,
  formatHints,
  hintLines,
  hintFileName,
  hintItems,
  hintKey,
  hintRef,
  hintsFor,
  hintApplies,
  isUnder,
  kindQuestion,
  normalize,
  parseHint,
  pendingFileName,
  pendingPathOf,
  parseRemoved,
  removalProposal,
  removeFromFile,
  resolvePath,
  reviewLines,
  serverKeyOf,
  serverLabel,
  targetsOf,
  textFlags,
  toolsByServer,
  withReview,
  withoutItems,
  withoutReview,
  type Hint,
