      "type": "number",
      "title": "Program timeout (seconds)",
      "description": "Wall-clock and CPU limit for one run_code program. Minimum 5.",
      "default": 120,
      "required": false
    },
    "blockDirectMcp": {
      "type": "boolean",
      "title": "Block direct MCP calls",
      "description": "Deny MCP tool calls the model makes directly, so it uses run_code. Calls from run_code still go through.",
      "default": false,
      "required": false
    },
    "approval": {
      "type": "string",
      "title": "Approval of nested MCP calls",
      "description": "program: approving run_code approves the MCP calls inside it that no permission rule decides (deny rules and organization limits still apply). per-call: each nested call has its own permission check; in auto mode this needs allow rules.",
      "options": [
        "program",
        "per-call"
      ],
      "default": "program",
      "required": false
    },
    "projectHints": {
      "type": "boolean",
      "title": "Load project hints",
      "description": "Also load usage hints from .claude/code-mode/hints/ in the project. Off by default: anyone who can commit to the project could use them to steer the model.",
      "default": false,
      "required": false
    },
    "projection": {
      "type": "boolean",
      "title": "Output projection",
      "description": "After each run, show the size and shape of each MCP result and keep the results in memory, so a later program can read one again with recall(n) and make no new call.",
      "default": true,
      "required": false
    },
    "metrics": {
      "type": "boolean",
      "title": "Record run metrics",
      "description": "Write one line per run_code run to ~/.claude/code-mode/metrics/: sizes and counts only, no data. For the output projection experiment.",
      "default": false,
      "required": false
    }
  }
}

